import { Injectable } from '@angular/core';
export interface Msg { id: number; kind: 'success' | 'error'; text: string; }
@Injectable({ providedIn: 'root' })
export class MessagesService {
  list: Msg[] = [];
  private n = 0;
  show(kind: 'success' | 'error', text: string) {
    const m = { id: this.n++, kind, text };
    this.list.push(m);
    setTimeout(() => this.close(m), 5000);
  }
  success(t: string) { this.show('success', t); }
  error(t: string) { this.show('error', t); }
  close(m: Msg) { this.list = this.list.filter((x) => x !== m); }
}
